const body = $json.body || {};
const q = (body.messageInput || '').toLowerCase();
const allowlist = [
  'trash','waste','recycle','recycling','compost','garbage','bin','landfill','plastic','paper','glass','metal',
  'e-waste','organic','hazardous','disposal','segregation','collection','pickup','schedule','litter','pollution',
  'sustainability','environment','eco','composting','reuse','reduce','sorting','incineration','municipal',
  'trashtrack','trash track','app','driver','route','dump','junk','debris','scrap','rubbish','refuse'
];
const inDomain = allowlist.some(k => q.includes(k));
if (!inDomain) {
  return [[], [{ json: { reply: 'I can help with TrashTrack and waste topics like recycling, composting, disposal rules, and pickup schedules. Please ask something in that area.' } }]];
}
return [items, []];

let text = ($json.reply || $json.answer || $json.output || '').toString();
text = text.replace(/<think>[\s\S]*?<\/think>/gi, '').replace(/<[^>]*>/g, '').trim();
const bad = ['illegal','dangerous','harmful'];
if (bad.some(b => text.toLowerCase().includes(b))) {
  text = 'I can’t provide that. Please follow safe, legal, and eco-friendly waste practices. How can I help with recycling, composting, or TrashTrack features?';
}
return [{ reply: text }];
